using Retroscope.Core.Security;

namespace Retroscope.Core.Tests.Security;

[Trait("Category", "Security")]
public sealed class BcryptTests {
    // Generated by golang.org/x/crypto/bcrypt v0.58.0 (the library GoTrue hashes with) at cost 10.
    private const string GoTrueSixCharHash = "$2a$10$6/9Q0A0VBki9ZWITkyLsP.fikMCefVUCk.vIZ1cRDukpsPrUxNp8u";
    private const string GoTruePassphraseHash = "$2a$10$WEi8MYhiDkmt/MW5Wzj8Y.1FI6lPTFZzd3y2kEBy7JRPQrNHQEooG";

    [Fact]
    public void GoTrue_hash_of_a_six_character_password_verifies() {
        Assert.True(Bcrypt.Verify("abc123", GoTrueSixCharHash));
    }

    [Fact]
    public void GoTrue_hash_of_a_passphrase_verifies() {
        Assert.True(Bcrypt.Verify("correct horse battery staple", GoTruePassphraseHash));
    }

    [Theory]
    [InlineData("abc124")]
    [InlineData("ABC123")]
    [InlineData("abc123 ")]
    [InlineData("")]
    public void Wrong_passwords_do_not_verify(string password) {
        Assert.False(Bcrypt.Verify(password, GoTrueSixCharHash));
    }

    [Fact]
    public void Same_hash_with_the_2b_prefix_verifies() {
        Assert.True(Bcrypt.Verify("abc123", "$2b$" + GoTrueSixCharHash[4..]));
    }

    [Theory]
    [InlineData(null)]
    [InlineData("")]
    [InlineData("abc123")]
    [InlineData("$2a$10$tooShort")]
    [InlineData("$argon2id$v=19$m=65536,t=3,p=4$c2FsdA$aGFzaA")]
    [InlineData("$2x$10$6/9Q0A0VBki9ZWITkyLsP.fikMCefVUCk.vIZ1cRDukpsPrUxNp8u")]
    [InlineData("$2a$10$6/9Q0A0VBki9ZWITkyLsP.fikMCefVUCk.vIZ1cRDukpsPrUxNp8u\n")]
    public void Malformed_hashes_never_verify_or_throw(string? hash) {
        Assert.False(Bcrypt.IsWellFormed(hash));
        Assert.False(Bcrypt.Verify("abc123", hash));
    }

    [Fact]
    public void New_hashes_are_2a_cost_10_and_verify() {
        var hash = Bcrypt.Hash("pässwörd-ünïcode");

        Assert.StartsWith("$2a$10$", hash, StringComparison.Ordinal);
        Assert.True(Bcrypt.IsWellFormed(hash));
        Assert.True(Bcrypt.Verify("pässwörd-ünïcode", hash));
    }

    [Fact]
    public void Passwords_are_compared_as_raw_utf8_without_normalization() {
        var composed = "caf\u00e9";
        var decomposed = "cafe\u0301";

        Assert.False(Bcrypt.Verify(decomposed, Bcrypt.Hash(composed)));
    }

    [Fact]
    public void Hashing_more_than_72_bytes_is_refused() {
        Assert.True(Bcrypt.Verify(new string('a', 72), Bcrypt.Hash(new string('a', 72))));
        Assert.Throws<ArgumentException>(() => Bcrypt.Hash(new string('a', 73)));
        Assert.Throws<ArgumentException>(() => Bcrypt.Hash(new string('é', 37)));
    }

    [Fact]
    public void Dummy_verify_is_always_false() {
        Assert.False(Bcrypt.DummyVerify("abc123"));
        Assert.False(Bcrypt.DummyVerify(""));
    }
}
